content.text:
const { Given, When, Then } = require('@cucumber/cucumber');
const assert = require('assert');

Given('the app is loaded with no todos', function () {
	this.reset();
});

Given('the app is loaded with the todos:', function (dataTable) {
	const rows = dataTable.hashes();
	const todos = rows.map((row, i) => ({
		id: i + 1,
		title: row.title,
		completed: false
	}));
	this.loadWithTodos(todos);
});

Given('the app is loaded with {int} todos titled {string}', function (count, title) {
	const todos = [];
	for (let i = 0; i < count; i++) {
		todos.push({ id: i + 1, title: title, completed: false });
	}
	this.loadWithTodos(todos);
});

Given('the app is loaded with {int} todo titled {string}', function (count, title) {
	const todos = [];
	for (let i = 0; i < count; i++) {
		todos.push({ id: i + 1, title: title, completed: false });
	}
	this.loadWithTodos(todos);
});

Given('every todo in the list has the completed state', function () {
	const current = this.doc.querySelectorAll('.todo-list li');
	const titles = Array.from(current).map(li => li.querySelector('label')?.textContent || '');
	const stored = JSON.parse(this.win.localStorage.getItem('todos-vanilla') || '[]');
	const todos = (stored.length > 0 ? stored : titles.map((t, i) => ({ id: i + 1, title: t, completed: false })))
		.map(t => ({ ...t, completed: true }));
	this.loadWithTodos(todos);
});

Given('one todo in the list has the completed state and the others do not', function () {
	const stored = JSON.parse(this.win.localStorage.getItem('todos-vanilla') || '[]');
