cat > debug-test.mjs << 'EOF'
import { Window } from "happy-dom";
import fs from "fs";
import path from "path";

const html = fs.readFileSync(path.resolve("index.html"), "utf-8");
const appJs = fs.readFileSync(path.resolve("js/app.js"), "utf-8");

const todos = [
  { id: 1, title: 'Buy milk', completed: false },
  { id: 2, title: 'Walk the dog', completed: true },
  { id: 3, title: 'Read book', completed: false }
];

const window = new Window();
const document = window.document;
document.write(html);
window.localStorage.setItem('todos-vanilla', JSON.stringify(todos));
window.eval(appJs);

console.log("Initial state:");
console.log("  location.hash:", window.location.hash);
console.log("  items:", document.querySelectorAll('.todo-list li').length);

// Try setting hash
window.location.hash = '#/active';
console.log("After hash set:");
console.log("  location.hash:", window.location.hash);
console.log("  items:", document.querySelectorAll('.todo-list li').length);

// Try dispatching hashchange
window.dispatchEvent(new window.HashChangeEvent('hashchange'));
console.log("After hashchange event:");
console.log("  items:", document.querySelectorAll('.todo-list li').length);

window.close();
EOF
node ./debug-test.mjs 2>&1
rm debug-test.mjs

